"use client";

import DeleteOutlineOutlinedIcon from "@mui/icons-material/DeleteOutlineOutlined";
import InsertDriveFileOutlinedIcon from "@mui/icons-material/InsertDriveFileOutlined";
import UploadFileOutlinedIcon from "@mui/icons-material/UploadFileOutlined";
import { Box, Button, Checkbox, CircularProgress, IconButton, Stack, Typography } from "@mui/material";
import { useEffect, useRef, useState, type ChangeEvent, type ReactNode } from "react";

import { apiClient } from "@/lib/http/apiClient";

export type FileActionCardFileItem = {
  contentType?: string;
  downloadUrl?: string;
  fileId?: string;
  fileName: string;
  size?: number;
};

type UploadedFileResponse = {
  content_type: string;
  download_url: string;
  file_id: string;
  original_filename: string;
  size: number;
};

export type FileActionCardFile = string | FileActionCardFileItem;

export type FileActionCardProps = {
  checked?: boolean;
  description?: string;
  files: FileActionCardFile[];
  onCheckedChange?: (checked: boolean) => void;
  onDeleteFile?: (fileName: string) => void;
  onFileClick?: (fileName: string, file?: FileActionCardFile) => void;
  onUpload?: () => void;
  onUploadComplete?: (file: FileActionCardFileItem) => void;
  title: ReactNode;
  uploadEndpoint?: string;
  uploadLabel?: string;
};

const DEFAULT_UPLOAD_ENDPOINT = "/files";

export function FileActionCard({
  checked,
  description = "No attached files.",
  files,
  onCheckedChange,
  onDeleteFile,
  onFileClick,
  onUpload,
  onUploadComplete,
  title,
  uploadEndpoint = DEFAULT_UPLOAD_ENDPOINT,
  uploadLabel = "Upload",
}: FileActionCardProps) {
  const inputRef = useRef<HTMLInputElement | null>(null);
  const [localFiles, setLocalFiles] = useState<FileActionCardFile[]>(files);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState<string | null>(null);

  useEffect(() => {
    setLocalFiles(files);
  }, [files]);

  const openFilePicker = () => {
    if (onUpload) {
      onUpload();
      return;
    }

    inputRef.current?.click();
  };

  const uploadFile = async (file: File) => {
    const formData = new FormData();
    formData.append("file", file);

    const response = await apiClient.post<UploadedFileResponse>(uploadEndpoint, formData, {
      headers: {
        "Content-Type": "multipart/form-data",
      },
    });

    const uploaded = response.data;
    const nextFile: FileActionCardFileItem = {
      contentType: uploaded.content_type,
      downloadUrl: normalizeDownloadUrl(uploaded.download_url),
      fileId: uploaded.file_id,
      fileName: uploaded.original_filename,
      size: uploaded.size,
    };

    setLocalFiles((current) => [...current, nextFile]);
    onUploadComplete?.(nextFile);
  };

  const handleUploadChange = async (event: ChangeEvent<HTMLInputElement>) => {
    const selectedFile = event.target.files?.[0];
    event.target.value = "";

    if (!selectedFile) {
      return;
    }

    setUploading(true);
    setUploadError(null);

    try {
      await uploadFile(selectedFile);
    } catch (error) {
      setUploadError(error instanceof Error ? error.message : "Upload failed.");
    } finally {
      setUploading(false);
    }
  };

  const resolveFileName = (file: FileActionCardFile) => (typeof file === "string" ? file : file.fileName);

  const resolveDownloadUrl = (file: FileActionCardFile) => {
    if (typeof file === "string") {
      return null;
    }

    if (file.downloadUrl) {
      return normalizeDownloadUrl(file.downloadUrl);
    }

    if (file.fileId) {
      return `/api/files/${file.fileId}`;
    }

    return null;
  };

  const handleFileClick = (file: FileActionCardFile) => {
    const fileName = resolveFileName(file);

    if (onFileClick) {
      onFileClick(fileName, file);
      return;
    }

    const downloadUrl = resolveDownloadUrl(file);
    if (!downloadUrl) {
      return;
    }

    const anchor = document.createElement("a");
    anchor.href = downloadUrl;
    anchor.rel = "noreferrer";
    anchor.target = "_self";
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
  };

  return (
    <Box
      sx={{
        border: "1px solid",
        borderColor: "divider",
        borderRadius: 1.5,
        bgcolor: "background.paper",
        boxShadow: "none",
        p: 1.25,
      }}
    >
      <Stack spacing={1}>
        <Box sx={{ alignItems: "center", display: "flex", justifyContent: "space-between", gap: 1 }}>
          <Box sx={{ alignItems: "center", display: "flex", gap: 0.5, minWidth: 0 }}>
            {typeof checked === "boolean" || onCheckedChange ? (
              <Checkbox
                checked={Boolean(checked)}
                onChange={(event) => onCheckedChange?.(event.target.checked)}
                size="small"
                sx={{ p: 0, color: "text.secondary", "&.Mui-checked": { color: "primary.main" } }}
              />
            ) : null}
            <Typography noWrap sx={{ color: "text.primary", fontSize: 13, fontWeight: 800 }}>
              {title}
            </Typography>
          </Box>

          <Button
            disabled={uploading}
            onClick={openFilePicker}
            size="small"
            startIcon={uploading ? <CircularProgress color="inherit" size={14} /> : <UploadFileOutlinedIcon />}
            sx={{ minWidth: 92, px: 1.25 }}
            variant="outlined"
          >
            {uploading ? "Uploading" : uploadLabel}
          </Button>
          <input ref={inputRef} hidden onChange={handleUploadChange} type="file" />
        </Box>

        <Box
          sx={{
            border: "1px dashed",
            borderColor: "divider",
            borderRadius: 1.25,
            bgcolor: "background.default",
            minHeight: 74,
            p: 1,
          }}
        >
          <Stack spacing={0.75}>
            {localFiles.length > 0 ? (
              localFiles.map((file) => {
                const fileName = resolveFileName(file);
                return (
                  <Box
                    key={typeof file === "string" ? file : file.fileId ?? file.fileName}
                    sx={{
                      alignItems: "center",
                      border: "1px solid",
                      borderColor: "divider",
                      borderRadius: 1,
                      bgcolor: "background.paper",
                      display: "flex",
                      gap: 1,
                      justifyContent: "space-between",
                      px: 1,
                      py: 0.5,
                    }}
                  >
                    <Button
                      onClick={() => handleFileClick(file)}
                      size="small"
                      startIcon={<InsertDriveFileOutlinedIcon />}
                      sx={{
                        color: "text.primary",
                        justifyContent: "flex-start",
                        minWidth: 0,
                        px: 0.5,
                        textTransform: "none",
                        width: "100%",
                      }}
                      variant="text"
                    >
                      <Typography noWrap sx={{ fontSize: 13, fontWeight: 600, textAlign: "left", width: "100%" }}>
                        {fileName}
                      </Typography>
                    </Button>

                    <Box sx={{ alignItems: "center", display: "flex", gap: 0.25, flex: "0 0 auto" }}>
                      {onDeleteFile ? (
                        <IconButton aria-label={`delete ${fileName}`} onClick={() => onDeleteFile(fileName)} size="small">
                          <DeleteOutlineOutlinedIcon fontSize="small" />
                        </IconButton>
                      ) : null}
                    </Box>
                  </Box>
                );
              })
            ) : (
              <Typography color="text.secondary" sx={{ py: 0.5 }} variant="body2">
                {description}
              </Typography>
            )}
          </Stack>

          {uploadError ? (
            <Typography color="error" sx={{ mt: 1 }} variant="caption">
              {uploadError}
            </Typography>
          ) : null}
        </Box>
      </Stack>
    </Box>
  );
}

function normalizeDownloadUrl(value: string) {
  if (value.startsWith("http://") || value.startsWith("https://")) {
    return value;
  }

  if (value.startsWith("/api/")) {
    return value;
  }

  if (value.startsWith("/")) {
    return `/api${value}`;
  }

  return `/api/${value}`;
}
